uint16_t cm_sleep_check(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){uint16_t f,patch,end,failures=0;cm_native_io io,old;exec_transfer next;if(n>=64u)return 1;cm_sleep_input(s,&io,cm_sleep_numbers[n]);memcpy(before,s,sizeof *s);old=io;if((uint16_t)cm_basic_sleep(s,&io,&next)!=cm_sleep_results[n])++failures;patch=cm_sleep_offsets[n];end=cm_sleep_offsets[n+1u];for(f=0;f<2051u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:f==2049u?old.interrupt_enabled:old.channel11;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:f==2049u?io.interrupt_enabled:io.channel11;if(patch<end&&cm_sleep_patch[patch][0]==f)expected=cm_sleep_patch[patch++][1];if(actual!=expected)++failures;}if(patch!=end)++failures;old.superbank=io.superbank;old.interrupt_enabled=io.interrupt_enabled;old.channel11=io.channel11;if(memcmp(&old,&io,sizeof io))++failures;if(s->words[5]==03231u){if(next.interpretive||next.address.location||next.address.bank)++failures;}else{if(next.interpretive!=(s->words[5]==06037u)||next.address.location!=(next.interpretive?s->words[0164]:s->words[5])||next.address.bank!=(uint16_t)(s->words[6]|io.superbank))++failures;}return failures;}
